  "implementation": "def solve(case):\\n    if not isinstance(case, dict) or 'payload' not in case:\\n        raise ValueError('Invalid case structure')\\n    payload = case['payload']\\n    if 'attempts' not in payload or 'max_attempts' not in payload:\\n        raise ValueError('Missing required fields')\\n    attempts = payload['attempts']\\n    max_attempts = payload['max_attempts']\\n    if not isinstance(attempts, list):\\n        raise ValueError('attempts must be list')\\n    if not isinstance(max_attempts, int) or max_attempts < 1:\\n        raise ValueError('invalid max_attempts')\\n    for i, att in enumerate(attempts):\\n        if not isinstance(att, dict) or 'success' not in att or 'failure_signature' not in att or 'reflection' not in att:\\n            raise ValueError(f'Invalid attempt at index {i}')\\n    num_attempts = len(attempts)\\n    last_attempt = attempts[-1] if attempts else None\\n    for att in attempts:\\n        if att['success']:\\n            return {\\n                'decision': 'success_terminate',\\n                'next_index': None,\\n                'memory_update': {'reflection': att['reflection'], 'failure_signature': att['failure_signature']}\\n            }\\n    if num_attempts >= max_attempts:\\n        return {\\n            'decision': 'budget_exhausted',\\n            'next_index': None,\\n            'memory_update': {'reflection': last_attempt['reflection'], 'failure_signature': last_attempt['failure_signature']}\\n        }\\n    signatures = [att['failure_signature'] for att in attempts]\\n    if len(signatures) != len(set(signatures)):\\n        return {\\n            'decision': 'repeated_signature',\\n            'next_index': None,\\n            'memory_update': {'reflection': last_attempt['reflection'], 'failure_signature': last_attempt['failure_signature']}\\n        }\\n    next_index = num_attempts\\n    if last_attempt:\\n        reflection = last_attempt['reflection']\\n        signature = last_attempt['failure_signature']\\n    else:\\n        reflection = ''\\n        signature = ''\\n    return {\\n        'decision': 'continue',\\n        'next_index': next_index,\\n        'memory_update': {'reflection': reflection, 'failure_signature': signature}\\n    }"
